    # End of the window that was actually queried, defaulting to now. The window is half-open, so an entry exactly at this instant is excluded. A window longer than 92 days is refused rather than truncated.
    requested_end: str
    # First entry timestamp actually covered, not the requested start. Equal to window_end when the window held no entries.
    window_start: str
    # Last entry timestamp actually covered, not the requested end.
    window_end: str
    # False when the trail lost entries in this window, which means the totals below are a floor rather than a measurement. Derived from drop_markers, never assumed.
    complete: bool
    # One line per agent credential that appears in the window, busiest first. A credential with no traffic is absent rather than zero.
    agents: list[AgentUsageLine]
    # Usage recorded against no credential: refused connections that never resolved one, control-plane sweep entries, and gap markers. Reported as its own line and never smeared across agents or dropped, so that the sum of agents plus unattributed equals totals exactly.
    unattributed: AgentUsageLine
    # The whole window. Equal to the sum of agents plus unattributed.
    totals: AgentUsageLine
