    # Short name for what this step demonstrates.
    title: str
    # The exact statement to run. Relations are schema-qualified on purpose.
    sql: str
    # The outcome the statement must produce. allow returns rows unchanged; masked returns rows with the listed columns replaced; blocked returns a PostgreSQL error rather than rows.
    expect: Literal["allow", "masked", "blocked"]
    # The decision rule named in the error, for a blocked step. Present only when expect is blocked.
    expect_rule: NotRequired[str]
    # Output columns that come back masked, for a masked step. Present only when expect is masked.
    expect_columns: NotRequired[list[DemoColumn]]
    # The policy rule that produces this outcome, in one sentence.
    why: str


