class DryEvalResult(TypedDict):
    """The decision the proxy would reach for the supplied statement under the supplied policy. verdict is the headline outcome; the remaining fields detail why."""

    # allow — permitted unchanged; block — rejected; mask — permitted but listed result columns are masked; row-filter — permitted but a WHERE predicate is injected (and any listed columns are also masked).
    verdict: Literal["allow", "block", "mask", "row-filter"]
    # Machine-readable decision tag. For a block, the blocking rule (e.g. read_only, table_denied, table_not_allowed, statement_denied, row_filter_unsafe). Otherwise "ok".
    rule: str
    # Human-readable explanation of the verdict.
    reason: str
    # What the author could do instead (present on block verdicts).
    hint: NotRequired[str]
    # Result columns that would be masked. Present on mask/row-filter verdicts.
    masked_columns: NotRequired[list[DryEvalMaskedColumn]]
    # The row-filter predicate ANDed into the statement's WHERE clause.
    row_filter_predicate: NotRequired[str]
    # The statement as it would be sent upstream after row-filter injection.
    rewritten_sql: NotRequired[str]
    # Informational caveats about stateful enforcement a single-statement preview cannot model (per-region budgets, approvals, write-mode routing).
    notes: NotRequired[list[str]]


class Error(TypedDict):
    """An RFC 9457 problem detail, served as `application/problem+json`. Every error the API returns has this shape."""

    # URI identifying the error condition. It resolves to that condition's entry in the published error catalog. This is the RFC 9457 identifier; `code` is the same identity as a short token.
    type: str
    # Short human-readable summary of the error condition.
    title: str
    # HTTP status code, repeated here so the document is self-contained.
    status: int
    # Human-readable explanation specific to this occurrence. Written for a person; branch on `code` or `type` rather than on this string.
    detail: NotRequired[str]
    # Path of the request that produced the error.
    instance: NotRequired[str]
    code: ErrorCode
    # Correlation id for this request, also returned in the `X-Request-Id` header. Quote it when reporting a problem.
    request_id: NotRequired[str]
    # Field-level detail, present when the request failed validation. Each entry names the part of the request that was rejected.
    errors: NotRequired[list[FieldError]]


# Machine-readable identity of the error condition. This is the value to branch on: it is stable across wording changes, and it distinguishes conditions that share a status code (a permissions denial from a plan limit, a duplicate name from a state conflict). New codes are added for new conditions, so treat the set as open and fall back on the status.
ErrorCode = Literal[
    "INVALID_INPUT",
    "UNSUPPORTED_MEDIA_TYPE",
    "PAYLOAD_TOO_LARGE",
    "METHOD_NOT_ALLOWED",
    "UNAUTHORIZED",
    "PAYMENT_REQUIRED",
    "FORBIDDEN",
    "PLAN_LIMIT_REACHED",
    "NOT_FOUND",
    "PRECONDITION_FAILED",
    "CONFLICT",
    "RESOURCE_EXISTS",
    "INVALID_STATE",
    "IDEMPOTENCY_KEY_REUSED",
    "RATE_LIMITED",
    "INTERNAL_ERROR",
    "BAD_GATEWAY",
    "SERVICE_UNAVAILABLE",
    "TIMEOUT",
    "DEMO_NOT_CONFIGURED",
    "DEMO_PAUSED",
    "DEMO_CAPACITY_FULL",
    "DEMO_BUSY",
    "DEMO_TIER_NOT_PURCHASABLE",
]


