class PolicyProfile(TypedDict):
    """A named bundle of rules enforced on agent credentials in the data plane."""

    # Unique policy profile identifier (prefixed).
    id: str
    # Owning project ID.
    project_id: str
    # Human-readable name for the policy profile.
    name: str
    # read_only blocks all data and schema mutations.
    access_mode: Literal["read_only", "read_write"]
    statement_rules: NotRequired[StatementRules]
    # If non-empty, only these relations are reachable. Entries are schema-qualified (billing.orders) or bare (orders); a bare entry grants the public schema only, so the same table name in another schema must be listed in full.
    table_allowlist: list[str]
    # Relations explicitly blocked (takes precedence over the allowlist). A bare entry blocks that relation in every schema.
    table_denylist: list[str]
    # Column masking rules applied to query results.
    masking_rules: list[MaskingRule]
    # Max queries per rolling hour window. 0 means unlimited.
    budget_queries_per_hour: NotRequired[int]
    # Max queries per day window. 0 means unlimited.
    budget_queries_per_day: NotRequired[int]
    # Max rows returned per query. 0 means unlimited.
    max_rows: NotRequired[int]
    # Upstream statement timeout for agent sessions. 0 uses the project default.
    statement_timeout_ms: NotRequired[int]
    # Per-relation row filters ANDed into agent reads.
    row_filters: NotRequired[list[RowFilter]]
    # How writes are handled. normal commits, rollback auto-rolls back, sandbox routes to an ephemeral branch.
    write_mode: NotRequired[Literal["normal", "rollback", "sandbox"]]
