class PolicyRecommendation(TypedDict):
    """A least-privilege policy derived from an agent credential's recorded audit history, together with the replay diff that proves the candidate would not newly block any statement the credential legitimately ran. Advisory only: this endpoint never creates, updates, or otherwise mutates a policy or a credential. A good recommendation has replay.summary.newly_blocked == 0."""

    # True when there was enough parseable, executed traffic to derive a candidate. When false, candidate and replay are omitted and message explains why no recommendation could be made.
    sufficient_history: bool
    # Present when sufficient_history is false; a clear explanation of why no recommendation could be produced (e.g. no executed traffic in the window).
    message: NotRequired[str]
    candidate: NotRequired[PolicyProfileInput]
    replay: NotRequired[PolicyReplayResult]
    # Distinct executed query shapes the candidate was derived from (blocked attempts are excluded from derivation).
    observed_queries: int
    # Recorded audit entries covered by the analyzed window.
    observed_entries: int
    # Start of the analyzed traffic window (inclusive).
    window_start: str
    # End of the analyzed traffic window (exclusive).
    window_end: str
    # Human-readable rationale for each tightening decision (e.g. why the candidate was downgraded to read-only, or how max_rows was chosen).
    notes: NotRequired[list[str]]


class PolicyRecommendationInput(TypedDict):
    """Optional parameters for a least-privilege policy recommendation. Every field is optional; an empty body analyzes the last 30 days of the credential's audit history."""

    # How many days of recorded audit history to analyze.
    lookback_days: NotRequired[int]
    # Maximum number of distinct query shapes to analyze and replay, newest first. Traffic is deduplicated by normalized query hash.
    limit: NotRequired[int]


class PolicyReplayInput(TypedDict):
    """A window of recorded agent traffic to replay plus the candidate policy to replay it against. Supply exactly one of policy_id (an existing saved policy) or policy (an unsaved draft, e.g. the in-progress editor form)."""

    # ID of an existing saved policy profile to replay against.
    policy_id: NotRequired[str]
    policy: NotRequired[PolicyProfileInput]
    # Restrict the replay to traffic recorded for one agent credential.
    credential_id: NotRequired[str]
    # Restrict the replay to traffic recorded for the agent credentials currently bound to this policy profile. Use it to preview a change to a live policy against the traffic that policy actually governs: without it the replay covers every credential in the project, including credentials bound to other profiles, whose behaviour saving this candidate cannot change. Mutually exclusive with credential_id.
    bound_policy_id: NotRequired[str]
    # Start of the traffic window (inclusive). Defaults to 7 days before end_ts.
    start_ts: NotRequired[str]
    # End of the traffic window (exclusive). Defaults to now.
    end_ts: NotRequired[str]
    # Maximum number of distinct queries to replay, newest first. Traffic is deduplicated by normalized query hash before evaluation.
    limit: NotRequired[int]


class PolicyReplayItem(TypedDict):
    """One distinct recorded query and the decision the candidate policy would reach for it."""

    # Normalized query hash identifying this statement shape.
    query_hash: str
    # The recorded statement (normalized, literals replaced with $N placeholders), from its most recent occurrence.
    sql: str
    # Statement kind (select, insert, update, delete, ddl, ...).
    statement_kind: NotRequired[str]
    # How many recorded entries share this query shape in the window.
    occurrences: int
    # Oldest occurrence in the window.
    first_seen: str
    # Newest occurrence in the window.
    last_seen: str
    # The most recent recorded outcome for this query (query, masked, truncated, or blocked).
    recorded_event: str
    # The decision rule recorded with a blocked outcome.
    recorded_rule: NotRequired[str]
    # How the candidate decision compares to the recorded outcome. newly_blocked and newly_allowed are the changes worth reviewing before rollout; still_allowed and still_blocked are unchanged.
    change: Literal["newly_blocked", "newly_allowed", "still_allowed", "still_blocked"]
    result: DryEvalResult


class PolicyReplayResult(TypedDict):
    """The outcome of replaying recorded agent traffic against a candidate policy: an aggregate summary plus per-query decisions, changes first."""

    summary: PolicyReplaySummary
    # Per-query replay decisions, ordered changes first (newly blocked, then newly allowed), then by occurrence count.
    items: list[PolicyReplayItem]


class PolicyReplaySummary(TypedDict):
    """Aggregate outcome of a policy replay."""

    # Which recorded traffic the replay covered. "project" is every credential in the project, so some replayed queries may belong to credentials this candidate policy does not govern. "bound_credentials" is only the credentials bound to bound_policy_id, which is what actually changes when that policy is saved.
    traffic_scope: Literal["project", "bound_credentials"]
    # How many agent credentials are bound to bound_policy_id. Set only when traffic_scope is bound_credentials. Zero means the policy governs no credential today, so an empty replay is a statement about bindings and not evidence that the change is safe.
    bound_credentials: NotRequired[int]
    # Recorded audit entries covered by the replayed queries.
    entries_scanned: int
    # Distinct normalized queries found in the window (capped at limit).
    distinct_queries: int
    # Distinct queries actually evaluated against the candidate policy.
    evaluated: int
    # Queries the candidate policy would allow unchanged.
    would_allow: int
    # Queries the candidate policy would block.
    would_block: int
    # Queries the candidate policy would mask result columns on.
    would_mask: int
    # Queries the candidate policy would inject a row filter into.
    would_row_filter: int
    # Queries that executed under the recorded policy but the candidate policy would block.
    newly_blocked: int
    # Queries that were blocked when recorded but the candidate policy would permit.
    newly_allowed: int
    # Distinct queries skipped because the stored statement was truncated at record time and can no longer be parsed faithfully.
    skipped_unparseable: int
    # True when the window contained more distinct queries than limit; only the newest were replayed.
    truncated: bool


