class ScanTextFinding(TypedDict):
    """One detection, naming the technique and the bytes that caused it. Findings are evidence, not a score: there is no arithmetic over them and no threshold to tune."""

    # Which detector family produced the finding. A structural finding is a byte-level fact with no ordinary explanation. A lexical finding is exact-phrase matching, which is a reason to look rather than proof.
    layer: Literal["structural", "lexical"]
    # What was found.
    technique: Literal[
        "invisible_run",
        "tag_smuggling",
        "bidi_override",
        "mixed_script",
        "instruction_phrase",
        "invalid_encoding",
        "truncated",
    ]
    # How well the finding is explained by an attack rather than by ordinary content. An ordered label, deliberately not a score.
    confidence: Literal["low", "medium", "high"]
    # Byte offset into the submitted text where the evidence starts, or -1 when the finding is about the value as a whole.
    offset: int
    # The offending substring with invisible codepoints rendered visible and the result truncated. Absent when include_evidence was false. This is your own submitted text handed back to you; PgBeam does not retain it.
    evidence: NotRequired[str]
    # One line explaining the finding, written to be read by a model.
    detail: str


class ScanTextQuota(TypedDict):
    """Where the caller stands against the free daily allowance and any units it has paid for. Reported on every answered scan so a caller can see the 402 coming instead of being surprised by it."""

    # Scans included per UTC day at no charge for this caller.
    free_limit: int
    # Free scans left in the current UTC day, after this one.
    free_remaining: int
    # Purchased scans left, after this one. Free allowance is spent first, so this only moves once the daily allowance is gone.
    paid_remaining: int
    # When the free allowance next resets (the next UTC midnight).
    resets_at: str


class ScanTextRequest(TypedDict):
    """One piece of untrusted text to inspect. The text is held in memory for the duration of the request and is never written to a log, a database, or an object store. See https://pgbeam.com/docs/prompt-scan for what that means precisely."""

    # The untrusted text to inspect, at most 65536 bytes. Longer input is rejected rather than half-scanned, so a caller with a large document chunks it and scans each chunk.
    text: str
    # Which detector families to run. Defaults to both. Pass ["structural"] alone for the layer that produces no false positives on ordinary text, at the cost of missing every attack that has no byte-level tell.
    layers: NotRequired[list[Literal["structural", "lexical"]]]
    # Whether each finding quotes the offending substring back to you. Defaults to true. Set false when the caller must not receive its own end users' text back in a response it will store or forward.
    include_evidence: NotRequired[bool]


class ScanTextResult(TypedDict):
    """The verdict on one piece of text, with the recommended action and the evidence behind it. Read `action` to decide what to do and `findings` to explain the decision to a human."""

    # What the scanner concluded. `unscannable` is distinct from `clean` on purpose: text nobody could read must never be reported as text nobody objected to.
    verdict: Literal["clean", "suspicious", "unscannable"]
    # The recommended next step, which is the field to branch on. `block` means a structural technique with no innocent explanation was found. `review` means something was found that a human or a second check should judge. `allow` means nothing was found by the layers you ran.
    action: Literal["allow", "review", "block"]
    # One line saying why that action was recommended.
    action_reason: str
    # What to do next, written for a model to read directly. PgBeam returns LLM-readable reasons everywhere it refuses something, and this endpoint follows the same rule.
    advice: str
    # The strongest confidence among the findings. Absent when there are no findings.
    highest_confidence: NotRequired[Literal["low", "medium", "high"]]
    # Whether any finding came from the structural layer. This is the predicate most callers want, because the structural layer is the one whose findings have no ordinary explanation.
    has_structural: bool
    # Every detection, in the order the detectors produced them.
    findings: list[ScanTextFinding]
    # How many bytes of the submitted text were inspected.
    scanned_bytes: int
    # Whether only a prefix of the text was inspected. Always false today, because oversized input is rejected rather than half-scanned.
    truncated: bool
    # The detector build that produced this verdict, so a verdict that changes between two calls can be attributed to a version rather than to chance.
    engine: str
    quota: ScanTextQuota


